contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // take one parameter to satisfy the shape checker
    function run(uint dummy) public payable {
        require(true);

        // observe depositsCount before
        uint before = c.depositsCount(); if (__ESBMC_reverted()) return;

        // perform the potentially state-changing call as its own top-level statement and capture revert
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // general rule: either the call reverted, or depositsCount is unchanged
        assert(reverted || c.depositsCount() == before);
    }

    receive() external payable {}
}

